Example <p>The example below shows the trait, and a <code>from_json()</code> constrained to <code>json</code> values and views: <code>get&lt;T&gt;()</code> on a view reads the view directly.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;type_traits&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json;

namespace ns
{
struct person
{
    std::string name;
    int age = 0;
};

// reads json values and views (of any document type), but nothing else
template &lt; typename J, typename std::enable_if &lt; nlohmann::is_json_view&lt;J&gt;::value || std::is_same&lt;J, json&gt;::value, int &gt;::type = 0 &gt;
void from_json(const J&amp; j, person&amp; p)
{
    p.name = j.at("name").template get&lt;std::string&gt;();
    p.age = j.at("age").template get&lt;int&gt;();
}
} // namespace ns

int main()
{
    std::cout &lt;&lt; std::boolalpha
              &lt;&lt; nlohmann::is_json_view&lt;nlohmann::json_view&gt;::value &lt;&lt; ' '
              &lt;&lt; nlohmann::is_json_view&lt;nlohmann::ordered_json_editable_view&gt;::value &lt;&lt; ' '
              &lt;&lt; nlohmann::is_json_view&lt;json&gt;::value &lt;&lt; '\n';

    const nlohmann::json_document doc = nlohmann::json_document::parse(R"({"name": "Ada", "age": 36})");
    const auto p = doc.root().get&lt;ns::person&gt;(); // reads the view, no json value is built
    std::cout &lt;&lt; p.name &lt;&lt; ' ' &lt;&lt; p.age &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true true false
Ada 36
</code></pre>

Example <p>The example below demonstrates how to use the type <code>nlohmann::json</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create a JSON object
    json j =
    {
        {"pi", 3.141},
        {"happy", true},
        {"name", "Niels"},
        {"nothing", nullptr},
        {
            "answer", {
                {"everything", 42}
            }
        },
        {"list", {1, 0, 2}},
        {
            "object", {
                {"currency", "USD"},
                {"value", 42.99}
            }
        }
    };

    // add new values
    j["new"]["key"]["value"] = {"another", "list"};

    // count elements
    auto s = j.size();
    j["size"] = s;

    // pretty print with indent of 4 spaces
    std::cout &lt;&lt; std::setw(4) &lt;&lt; j &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
    "answer": {
        "everything": 42
    },
    "happy": true,
    "list": [
        1,
        0,
        2
    ],
    "name": "Niels",
    "new": {
        "key": {
            "value": [
                "another",
                "list"
            ]
        }
    },
    "nothing": null,
    "object": {
        "currency": "USD",
        "value": 42.99
    },
    "pi": 3.141,
    "size": 8
}
</code></pre>

Example <p>The example below demonstrates how to use the type <code>nlohmann::json_document</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json_document;

int main()
{
    std::cout &lt;&lt; std::boolalpha;

    // json_document is basic_json_document&lt;nlohmann::json&gt;: same value types
    // and containers as the ordinary json specialization
    json_document doc = json_document::parse(R"({"pi": 3.14, "numbers": [1, 2, 3]})");

    std::cout &lt;&lt; doc.root().is_object() &lt;&lt; '\n';
    std::cout &lt;&lt; doc.root().materialize().dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true
{"numbers":[1,2,3],"pi":3.14}
</code></pre>

Example <p>The example below patches two fields of a small configuration document — changing one and adding another — and dumps it back out with the member order and the spelling of the untouched number preserved, something a plain <code>json</code> value cannot do.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json;
using nlohmann::json_editable_document;
using nlohmann::json_editable_view;

int main()
{
    // a configuration file, as it might be read from disk
    const std::string text = R"({"name": "cache", "host": "db1", "port": 6379, "price": 19.90})";
    std::cout &lt;&lt; text &lt;&lt; "\n\n";

    // patch two fields -- "price" is never touched
    json_editable_document doc = json_editable_document::parse(text);
    doc.set(doc.root(), "host", "db2");
    doc.set(doc.root(), "retries", 3);

    // member order (the new member at the end) and the untouched number's
    // exact spelling survive
    std::cout &lt;&lt; doc.root().dump(-1, ' ', false, json_editable_view::number_format::source) &lt;&lt; '\n';

    // the same patch on a plain json value: keys are sorted (object_t is a
    // std::map), and "price" is rewritten even though the patch never
    // touched it
    json plain = json::parse(text);
    plain["host"] = "db2";
    plain["retries"] = 3;
    std::cout &lt;&lt; plain.dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"name": "cache", "host": "db1", "port": 6379, "price": 19.90}

{"name":"cache","host":"db2","port":6379,"price":19.90,"retries":3}
{"host":"db2","name":"cache","port":6379,"price":19.9,"retries":3}
</code></pre>

Example <p>The example below is the same as <code>json_editable_document</code>'s: every view read back out of the document — <code>doc.root()</code> and the views nested under it — sees the edits made through <code>set</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json;
using nlohmann::json_editable_document;
using nlohmann::json_editable_view;

int main()
{
    // a configuration file, as it might be read from disk
    const std::string text = R"({"name": "cache", "host": "db1", "port": 6379, "price": 19.90})";
    std::cout &lt;&lt; text &lt;&lt; "\n\n";

    // patch two fields -- "price" is never touched
    json_editable_document doc = json_editable_document::parse(text);
    doc.set(doc.root(), "host", "db2");
    doc.set(doc.root(), "retries", 3);

    // member order (the new member at the end) and the untouched number's
    // exact spelling survive
    std::cout &lt;&lt; doc.root().dump(-1, ' ', false, json_editable_view::number_format::source) &lt;&lt; '\n';

    // the same patch on a plain json value: keys are sorted (object_t is a
    // std::map), and "price" is rewritten even though the patch never
    // touched it
    json plain = json::parse(text);
    plain["host"] = "db2";
    plain["retries"] = 3;
    std::cout &lt;&lt; plain.dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"name": "cache", "host": "db1", "port": 6379, "price": 19.90}

{"name":"cache","host":"db2","port":6379,"price":19.90,"retries":3}
{"host":"db2","name":"cache","port":6379,"price":19.9,"retries":3}
</code></pre>

Example <p>The example below demonstrates how to use the type <code>nlohmann::json_view</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

int main()
{
    std::cout &lt;&lt; std::boolalpha;

    // json_view is basic_json_view&lt;nlohmann::json&gt;: a read-only handle
    // returned by json_document::root()
    nlohmann::json_document doc = nlohmann::json_document::parse("[1, 2, 3]");
    nlohmann::json_view v = doc.root();

    std::cout &lt;&lt; v.is_array() &lt;&lt; ' ' &lt;&lt; v.size() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true 3
</code></pre>

Example <p>The example below shows how a JSON value is constructed by reading a serialization from a stream.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;sstream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create stream with serialized JSON
    std::stringstream ss;
    ss &lt;&lt; R"({
        "number": 23,
        "string": "Hello, world!",
        "array": [1, 2, 3, 4, 5],
        "boolean": false,
        "null": null
    })";

    // create JSON value and read the serialization from the stream
    json j;
    ss &gt;&gt; j;

    // serialize JSON
    std::cout &lt;&lt; std::setw(2) &lt;&lt; j &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
  "array": [
    1,
    2,
    3,
    4,
    5
  ],
  "boolean": false,
  "null": null,
  "number": 23,
  "string": "Hello, world!"
}
</code></pre>

Example <p>The following code shows how to create JSON values from string literals.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    json j = R"( {"hello": "world", "answer": 42} )"_json;

    std::cout &lt;&lt; std::setw(2) &lt;&lt; j &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
  "answer": 42,
  "hello": "world"
}
</code></pre>

Example <p>The following code shows how to create JSON Pointers from string literals.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    json j = R"( {"hello": "world", "answer": 42} )"_json;
    auto val = j["/hello"_json_pointer];

    std::cout &lt;&lt; std::setw(2) &lt;&lt; val &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>"world"
</code></pre>

Example: (1) serialize JSON value to stream <p>The example below shows the serialization with different parameters to <code>width</code> to adjust the indentation level.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create JSON values
    json j_object = {{"one", 1}, {"two", 2}};
    json j_array = {1, 2, 4, 8, 16};

    // serialize without indentation
    std::cout &lt;&lt; j_object &lt;&lt; "\n\n";
    std::cout &lt;&lt; j_array &lt;&lt; "\n\n";

    // serialize with indentation
    std::cout &lt;&lt; std::setw(4) &lt;&lt; j_object &lt;&lt; "\n\n";
    std::cout &lt;&lt; std::setw(2) &lt;&lt; j_array &lt;&lt; "\n\n";
    std::cout &lt;&lt; std::setw(1) &lt;&lt; std::setfill('\t') &lt;&lt; j_object &lt;&lt; "\n\n";
}
</code></pre> <p>Output:</p> <pre><code>{"one":1,"two":2}

[1,2,4,8,16]

{
    "one": 1,
    "two": 2
}

[
  1,
  2,
  4,
  8,
  16
]

{
    "one": 1,
    "two": 2
}
</code></pre> Example: (2) write JSON pointer to stream <p>The example below shows how to write a JSON pointer to a stream.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create JSON pointer
    json::json_pointer ptr("/foo/bar/baz");

    // write string representation to stream
    std::cout &lt;&lt; ptr &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>/foo/bar/baz
</code></pre>

Example <p>The example below demonstrates how <code>ordered_json</code> preserves the insertion order of object keys.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::ordered_json;

int main()
{
    ordered_json j;
    j["one"] = 1;
    j["two"] = 2;
    j["three"] = 3;

    std::cout &lt;&lt; j.dump(2) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
  "one": 1,
  "two": 2,
  "three": 3
}
</code></pre>

Example <p>The example below demonstrates how <code>ordered_json_document</code> preserves the insertion order of object keys when materializing.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::ordered_json_document;

int main()
{
    // ordered_json_document is basic_json_document&lt;nlohmann::ordered_json&gt;:
    // materialize() preserves the insertion (source) order of object keys,
    // instead of sorting them like json_document does
    ordered_json_document doc = ordered_json_document::parse(R"({"z": 1, "a": 2, "m": 3})");
    std::cout &lt;&lt; doc.root().materialize().dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"z":1,"a":2,"m":3}
</code></pre>

Example <p>The example below edits a document with <code>set</code>, then shows that <code>materialize()</code> keeps the member order of the source text (with the new member at the end) for <code>ordered_json_editable_document</code>, where it would sort the members alphabetically for <code>json_editable_document</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::ordered_json_editable_document;

int main()
{
    // ordered_json_editable_document is basic_json_document&lt;nlohmann::ordered_json, nlohmann::view_mode::editable&gt;
    ordered_json_editable_document doc = ordered_json_editable_document::parse(R"({"z": 1, "a": 2, "m": 3})");
    doc.set(doc.root(), "b", 4); // set() always appends a new member at the end

    // materialize() preserves the document order (with "b" at the end),
    // instead of sorting the keys the way json_editable_document does
    std::cout &lt;&lt; doc.root().materialize().dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"z":1,"a":2,"m":3,"b":4}
</code></pre>

Example <p>The example below is the same as <code>ordered_json_editable_document</code>'s: the views <code>set</code> returns see the document's member order preserved on <code>materialize()</code>, unlike for a <code>json_editable_document</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::ordered_json_editable_document;

int main()
{
    // ordered_json_editable_document is basic_json_document&lt;nlohmann::ordered_json, nlohmann::view_mode::editable&gt;
    ordered_json_editable_document doc = ordered_json_editable_document::parse(R"({"z": 1, "a": 2, "m": 3})");
    doc.set(doc.root(), "b", 4); // set() always appends a new member at the end

    // materialize() preserves the document order (with "b" at the end),
    // instead of sorting the keys the way json_editable_document does
    std::cout &lt;&lt; doc.root().materialize().dump() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"z":1,"a":2,"m":3,"b":4}
</code></pre>

Example <p>The example below demonstrates how to use the type <code>nlohmann::ordered_json_view</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

int main()
{
    nlohmann::ordered_json_document doc = nlohmann::ordered_json_document::parse(R"({"z": 1, "a": 2})");
    nlohmann::ordered_json_view v = doc.root();

    std::cout &lt;&lt; std::boolalpha &lt;&lt; v.is_object() &lt;&lt; ' ' &lt;&lt; v.size() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true 2
</code></pre>

Example <p>The example shows the different behavior of <code>std::map</code> and <code>nlohmann::ordered_map</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

// simple output function
template&lt;typename Map&gt;
void output(const char* prefix, const Map&amp; m)
{
    std::cout &lt;&lt; prefix &lt;&lt; " = { ";
    for (auto&amp; element : m)
    {
        std::cout &lt;&lt; element.first &lt;&lt; ":" &lt;&lt; element.second &lt;&lt; ' ';
    }
    std::cout &lt;&lt; "}" &lt;&lt; '\n';
}

int main()
{
    // create and fill two maps
    nlohmann::ordered_map&lt;std::string, std::string&gt; m_ordered;
    m_ordered["one"] = "eins";
    m_ordered["two"] = "zwei";
    m_ordered["three"] = "drei";

    std::map&lt;std::string, std::string&gt; m_std;
    m_std["one"] = "eins";
    m_std["two"] = "zwei";
    m_std["three"] = "drei";

    // output: m_ordered is ordered by insertion order, m_std is ordered by key
    output("m_ordered", m_ordered);
    output("m_std", m_std);

    // erase and re-add "one" key
    m_ordered.erase("one");
    m_ordered["one"] = "eins";

    m_std.erase("one");
    m_std["one"] = "eins";

    // output: m_ordered shows newly added key at the end; m_std is again ordered by key
    output("m_ordered", m_ordered);
    output("m_std", m_std);
}
</code></pre> <p>Output:</p> <pre><code>m_ordered = { one:eins two:zwei three:drei }
m_std = { one:eins three:drei two:zwei }
m_ordered = { two:zwei three:drei one:eins }
m_std = { one:eins three:drei two:zwei }
</code></pre>

Example <p>The example below shows a function template that accepts the views of both modes, one that accepts only views of editable documents, and a function taking a <code>json_editable_view</code> that also accepts a view of a read-only document.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::basic_json_view;
using nlohmann::view_mode;

// accepts the views of read-only and of editable documents, of json and of ordered_json
template&lt;typename BasicJsonType, view_mode Mode&gt;
std::size_t count_members(basic_json_view&lt;BasicJsonType, Mode&gt; v)
{
    return v.is_object() ? v.size() : 0;
}

// accepts only the views of editable documents
template&lt;typename BasicJsonType&gt;
bool is_edited(basic_json_view&lt;BasicJsonType, view_mode::editable&gt; v)
{
    return v.is_string() &amp;&amp; v.get_string() == "edited";
}

// a function (no template) taking a json_editable_view also accepts the view of a read-only document
std::size_t size_of(nlohmann::json_editable_view v)
{
    return v.size();
}

int main()
{
    const nlohmann::json_document doc = nlohmann::json_document::parse(R"({"a": 1, "b": 2})");
    nlohmann::json_editable_document edoc = nlohmann::json_editable_document::parse(R"({"a": 1})");
    edoc.set(edoc.root()["a"], "edited");

    std::cout &lt;&lt; count_members(doc.root()) &lt;&lt; ' ' &lt;&lt; count_members(edoc.root()) &lt;&lt; '\n';
    std::cout &lt;&lt; std::boolalpha &lt;&lt; is_edited(edoc.root()["a"]) &lt;&lt; '\n';
    std::cout &lt;&lt; size_of(doc.root()) &lt;&lt; ' ' &lt;&lt; size_of(edoc.root()) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>2 1
true
2 1
</code></pre>

Example: (1) Default-constructible type <p>The example below shows how a <code>from_json</code> function can be implemented for a user-defined type. This function is called by the <code>adl_serializer</code> when <code>get&lt;ns::person&gt;()</code> is called.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
// a simple struct to model a person
struct person
{
    std::string name;
    std::string address;
    int age;
};
} // namespace ns

namespace ns
{
void from_json(const json&amp; j, person&amp; p)
{
    j.at("name").get_to(p.name);
    j.at("address").get_to(p.address);
    j.at("age").get_to(p.age);
}
} // namespace ns

int main()
{
    json j;
    j["name"] = "Ned Flanders";
    j["address"] = "744 Evergreen Terrace";
    j["age"] = 60;

    auto p = j.get&lt;ns::person&gt;();

    std::cout &lt;&lt; p.name &lt;&lt; " (" &lt;&lt; p.age &lt;&lt; ") lives in " &lt;&lt; p.address &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>Ned Flanders (60) lives in 744 Evergreen Terrace
</code></pre> Example: (2) Non-default-constructible type <p>The example below shows how a <code>from_json</code> is implemented as part of a specialization of the <code>adl_serializer</code> to realize the conversion of a non-default-constructible type.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
// a simple struct to model a person (not default constructible)
struct person
{
    person(std::string n, std::string a, int aa)
        : name(std::move(n)), address(std::move(a)), age(aa)
    {}

    std::string name;
    std::string address;
    int age;
};
} // namespace ns

namespace nlohmann
{
template &lt;&gt;
struct adl_serializer&lt;ns::person&gt;
{
    static ns::person from_json(const json&amp; j)
    {
        return {j.at("name"), j.at("address"), j.at("age")};
    }

    // Here's the catch! You must provide a to_json method! Otherwise, you
    // will not be able to convert person to json, since you fully
    // specialized adl_serializer on that type
    static void to_json(json&amp; j, ns::person p)
    {
        j["name"] = p.name;
        j["address"] = p.address;
        j["age"] = p.age;
    }
};
} // namespace nlohmann

int main()
{
    json j;
    j["name"] = "Ned Flanders";
    j["address"] = "744 Evergreen Terrace";
    j["age"] = 60;

    auto p = j.get&lt;ns::person&gt;();

    std::cout &lt;&lt; p.name &lt;&lt; " (" &lt;&lt; p.age &lt;&lt; ") lives in " &lt;&lt; p.address &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>Ned Flanders (60) lives in 744 Evergreen Terrace
</code></pre>

Example <p>The example below shows how a <code>to_json</code> function can be implemented for a user-defined type. This function is called by the <code>adl_serializer</code> when the constructor <code>basic_json(ns::person)</code> is called.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
// a simple struct to model a person
struct person
{
    std::string name;
    std::string address;
    int age;
};
} // namespace ns

namespace ns
{
void to_json(json&amp; j, const person&amp; p)
{
    j = json{ {"name", p.name}, {"address", p.address}, {"age", p.age} };
}
} // namespace ns

int main()
{
    ns::person p = {"Ned Flanders", "744 Evergreen Terrace", 60};

