Example: (1) reading from a string <p>The example below demonstrates the <code>accept()</code> function reading from a string.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // a valid JSON text
    const auto* valid_text = R"(
    {
        "numbers": [1, 2, 3]
    }
    )";

    // an invalid JSON text
    const auto* invalid_text = R"(
    {
        "strings": ["extra", "comma", ]
    }
    )";

    std::cout &lt;&lt; std::boolalpha
              &lt;&lt; json::accept(valid_text) &lt;&lt; ' '
              &lt;&lt; json::accept(invalid_text) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true false
</code></pre> Example: (2) reading from an iterator pair <p>The example below demonstrates the <code>accept()</code> function reading from an iterator pair. Only the first call covers exactly the JSON text; the second one also covers the trailing bytes and is therefore rejected.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // a buffer containing a JSON text followed by more data
    std::vector&lt;std::uint8_t&gt; input = {'[', '1', ',', '2', ',', '3', ']', 'o', 't', 'h', 'e', 'r'};

    std::cout &lt;&lt; std::boolalpha
              &lt;&lt; json::accept(input.begin(), input.begin() + 7) &lt;&lt; ' '
              &lt;&lt; json::accept(input.begin(), input.end()) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true false
</code></pre> Example: (3) reading from UTF-16 strings <p>The encoding is deduced from the character type of the input. String literals like <code>u"..."</code>, <code>U"..."</code>, and <code>L"..."</code> work as well.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // a valid JSON text, given as UTF-16
    const std::u16string valid_text = u"{\"name\":\"\u00e9\"}";

    // an invalid JSON text, given as UTF-16
    const std::u16string invalid_text = u"{\"name\":\"\u00e9\",}";

    std::cout &lt;&lt; std::boolalpha
              &lt;&lt; json::accept(valid_text) &lt;&lt; ' '
              &lt;&lt; json::accept(invalid_text) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true false
</code></pre>

