Example <p>The example shows how to use <code>as_base_class</code> to access members of the custom base class that are hidden by members of <code>basic_json</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

class base_class_with_hidden_members
{
  public:
    const char* type_name() const noexcept
    {
        return "my_type_name";
    }

    std::size_t size() const noexcept
    {
        return 42;
    }
};

using json = nlohmann::json::with_base_class_t&lt;base_class_with_hidden_members&gt;;

int main()
{
    json j = {1, 2, 3};

    // the members of basic_json hide the members of the base class
    std::cout &lt;&lt; j.type_name() &lt;&lt; ' ' &lt;&lt; j.size() &lt;&lt; '\n';

    // access the hidden members of the base class
    std::cout &lt;&lt; j.as_base_class().type_name() &lt;&lt; ' ' &lt;&lt; j.as_base_class().size() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>array 3
my_type_name 42
</code></pre>

Example: (1) access specified array element with bounds checking <p>The example below shows how array elements can be read and written using <code>at()</code>. It also demonstrates the different exceptions that can be thrown.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create JSON array
    json array = {"first", "2nd", "third", "fourth"};

    // output element at index 2 (third element)
    std::cout &lt;&lt; array.at(2) &lt;&lt; '\n';

    // change element at index 1 (second element) to "second"
    array.at(1) = "second";

    // output changed array
    std::cout &lt;&lt; array &lt;&lt; '\n';

    // exception type_error.304
    try
    {
        // use at() on a non-array type
        json str = "I am a string";
        str.at(0) = "Another string";
    }
    catch (const json::type_error&amp; e)
    {
        std::cout &lt;&lt; e.what() &lt;&lt; '\n';
    }

    // exception out_of_range.401
    try
    {
        // try to write beyond the array limit
        array.at(5) = "sixth";
    }
    catch (const json::out_of_range&amp; e)
    {
        std::cout &lt;&lt; e.what() &lt;&lt; '\n';
    }
}
