Example <p>The following code shows an example for <code>back()</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create JSON values
    json j_boolean = true;
    json j_number_integer = 17;
    json j_number_float = 23.42;
    json j_object = {{"one", 1}, {"two", 2}};
    json j_object_empty(json::value_t::object);
    json j_array = {1, 2, 4, 8, 16};
    json j_array_empty(json::value_t::array);
    json j_string = "Hello, world";

    // call back()
    std::cout &lt;&lt; j_boolean.back() &lt;&lt; '\n';
    std::cout &lt;&lt; j_number_integer.back() &lt;&lt; '\n';
    std::cout &lt;&lt; j_number_float.back() &lt;&lt; '\n';
    std::cout &lt;&lt; j_object.back() &lt;&lt; '\n';
