Example: (1) explicit conversion to compatible types <p>The example below shows several conversions from JSON values to other types. There a few things to note: (1) Floating-point numbers can be converted to integers, (2) A JSON array can be converted to a standard <code>std::vector&lt;short&gt;</code>, (3) A JSON object can be converted to C++ associative containers such as <code>std::map&lt;std::string, json&gt;</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create a JSON value with different types
    json json_types =
    {
        {"boolean", true},
        {
            "number", {
                {"integer", 42},
                {"floating-point", 17.23}
            }
        },
        {"string", "Hello, world!"},
        {"array", {1, 2, 3, 4, 5}},
        {"null", nullptr}
    };

    // use explicit conversions
    auto v1 = json_types["boolean"].get&lt;bool&gt;();
    auto v2 = json_types["number"]["integer"].get&lt;int&gt;();
    auto v3 = json_types["number"]["integer"].get&lt;short&gt;();
    auto v4 = json_types["number"]["floating-point"].get&lt;float&gt;();
    auto v5 = json_types["number"]["floating-point"].get&lt;int&gt;();
    auto v6 = json_types["string"].get&lt;std::string&gt;();
    auto v7 = json_types["array"].get&lt;std::vector&lt;short&gt;&gt;();
    auto v8 = json_types.get&lt;std::map&lt;std::string, json&gt;&gt;();

    // print the conversion results
    std::cout &lt;&lt; v1 &lt;&lt; '\n';
    std::cout &lt;&lt; v2 &lt;&lt; ' ' &lt;&lt; v3 &lt;&lt; '\n';
    std::cout &lt;&lt; v4 &lt;&lt; ' ' &lt;&lt; v5 &lt;&lt; '\n';
    std::cout &lt;&lt; v6 &lt;&lt; '\n';

    for (auto i : v7)
    {
        std::cout &lt;&lt; i &lt;&lt; ' ';
    }
    std::cout &lt;&lt; "\n\n";

    for (const auto&amp; i : v8)
    {
        std::cout &lt;&lt; i.first &lt;&lt; ": " &lt;&lt; i.second &lt;&lt; '\n';
    }
}
</code></pre> <p>Output:</p> <pre><code>1
42 42
17.23 17
Hello, world!
1 2 3 4 5 

array: [1,2,3,4,5]
boolean: true
null: null
number: {"floating-point":17.23,"integer":42}
string: "Hello, world!"
</code></pre> Example: (2) explicit conversion to another <code>basic_json</code> specialization <p>The example below shows how a <code>json</code> value is converted to an <code>ordered_json</code> value using <code>get&lt;BasicJsonType&gt;()</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using nlohmann::ordered_json;

int main()
{
    // create a JSON value
    json j = {{"one", 1}, {"two", 2}, {"three", 3}};

    // convert to a different basic_json specialization
    ordered_json oj = j.get&lt;ordered_json&gt;();

    std::cout &lt;&lt; j &lt;&lt; '\n';
    std::cout &lt;&lt; oj &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"one":1,"three":3,"two":2}
{"one":1,"three":3,"two":2}
</code></pre> Example: (3) explicit pointer access to the stored value <p>The example below shows how pointers to internal values of a JSON value can be requested. Note that no type conversions are made and a <code>#cpp nullptr</code> is returned if the value and the requested pointer type does not match.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create a JSON number
    json value = 17;

    // explicitly getting pointers
    const auto* p1 = value.get&lt;const json::number_integer_t*&gt;();
    auto* p2 = value.get&lt;json::number_integer_t*&gt;();
    auto* p3 = value.get&lt;json::number_integer_t* const&gt;();
    const auto* p4 = value.get&lt;const json::number_integer_t* const&gt;();
    auto* p5 = value.get&lt;json::number_float_t*&gt;();

    // print the pointees
    std::cout &lt;&lt; *p1 &lt;&lt; ' ' &lt;&lt; *p2 &lt;&lt; ' ' &lt;&lt; *p3 &lt;&lt; ' ' &lt;&lt; *p4 &lt;&lt; '\n';
    std::cout &lt;&lt; std::boolalpha &lt;&lt; (p5 == nullptr) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>17 17 17 17
true
