Example <p>The following code shows how to inject custom data and methods for each node.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

class visitor_adaptor_with_metadata
{
  public:
    template &lt;class Fnc&gt;
    void visit(const Fnc&amp; fnc) const;

    int metadata = 42;
  private:
    template &lt;class Ptr, class Fnc&gt;
    void do_visit(const Ptr&amp; ptr, const Fnc&amp; fnc) const;
};

using json = nlohmann::json::with_base_class_t&lt;visitor_adaptor_with_metadata&gt;;

template &lt;class Fnc&gt;
void visitor_adaptor_with_metadata::visit(const Fnc&amp; fnc) const
{
    do_visit(json::json_pointer{}, fnc);
}

template &lt;class Ptr, class Fnc&gt;
void visitor_adaptor_with_metadata::do_visit(const Ptr&amp; ptr, const Fnc&amp; fnc) const
{
    using nlohmann::detail::value_t;
    const json&amp; j = *static_cast&lt;const json*&gt;(this);
    switch (j.type())
    {
        case value_t::object:
            fnc(ptr, j);
            for (const auto&amp; entry : j.items())
            {
                entry.value().do_visit(ptr / entry.key(), fnc);
            }
            break;
        case value_t::array:
            fnc(ptr, j);
            for (std::size_t i = 0; i &lt; j.size(); ++i)
            {
                j.at(i).do_visit(ptr / std::to_string(i), fnc);
            }
            break;
        case value_t::null:
        case value_t::string:
        case value_t::boolean:
        case value_t::number_integer:
        case value_t::number_unsigned:
        case value_t::number_float:
        case value_t::binary:
            fnc(ptr, j);
            break;
        case value_t::discarded:
        default:
            break;
    }
}

int main()
{
    // create a json object
    json j;
    j["null"];
    j["object"]["uint"] = 1U;
    j["object"].metadata = 21;

    // visit and output
    j.visit(
         [&amp;](const json::json_pointer &amp; p,
             const json &amp; j)
    {
        std::cout &lt;&lt; (p.empty() ? std::string{"/"} : p.to_string())
                  &lt;&lt; " - metadata = " &lt;&lt; j.metadata &lt;&lt; " -&gt; " &lt;&lt; j.dump() &lt;&lt; '\n';
    });
}
</code></pre> <p>Output:</p> <pre><code>/ - metadata = 42 -&gt; {"null":null,"object":{"uint":1}}
/null - metadata = 42 -&gt; null
/object - metadata = 21 -&gt; {"uint":1}
/object/uint - metadata = 42 -&gt; 1
</code></pre>

Example <p>The example below shows how a conversion of a non-default-constructible type is implemented via a specialization of the <code>adl_serializer</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
// a simple struct to model a person (not default constructible)
struct person
{
    person(std::string n, std::string a, int aa)
        : name(std::move(n)), address(std::move(a)), age(aa)
    {}

    std::string name;
    std::string address;
    int age;
};
} // namespace ns

namespace nlohmann
{
template &lt;&gt;
struct adl_serializer&lt;ns::person&gt;
{
    static ns::person from_json(const json&amp; j)
    {
        return {j.at("name"), j.at("address"), j.at("age")};
    }

    // Here's the catch! You must provide a to_json method! Otherwise, you
    // will not be able to convert person to json, since you fully
    // specialized adl_serializer on that type
    static void to_json(json&amp; j, ns::person p)
    {
        j["name"] = p.name;
        j["address"] = p.address;
        j["age"] = p.age;
    }
};
} // namespace nlohmann

int main()
{
    json j;
    j["name"] = "Ned Flanders";
    j["address"] = "744 Evergreen Terrace";
    j["age"] = 60;

    auto p = j.get&lt;ns::person&gt;();

    std::cout &lt;&lt; p.name &lt;&lt; " (" &lt;&lt; p.age &lt;&lt; ") lives in " &lt;&lt; p.address &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>Ned Flanders (60) lives in 744 Evergreen Terrace
</code></pre>

