Example <p>The following code shows how a JSON Merge Patch is created as a diff for two JSON values.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    // the source document
    json source = R"(
        {
            "title": "Goodbye!",
            "author": {
                "givenName": "John",
                "familyName": "Doe"
            },
            "tags": [
                "example",
                "sample"
            ],
            "content": "This will be unchanged"
        }
    )"_json;

    // the target document
    json target = R"(
        {
            "title": "Hello!",
            "author": {
                "givenName": "John"
            },
            "tags": [
                "example"
            ],
            "content": "This will be unchanged",
            "phoneNumber": "+01-123-456-7890"
        }
    )"_json;

    // create the patch
    json patch = json::merge_diff(source, target);

    // roundtrip
    json patched_source = source;
    patched_source.merge_patch(patch);

    // output patch and roundtrip result
    std::cout &lt;&lt; std::setw(4) &lt;&lt; patch &lt;&lt; "\n\n"
              &lt;&lt; std::setw(4) &lt;&lt; patched_source &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
    "author": {
        "familyName": null
    },
    "phoneNumber": "+01-123-456-7890",
    "tags": [
        "example"
    ],
    "title": "Hello!"
}

{
    "author": {
        "givenName": "John"
    },
    "content": "This will be unchanged",
    "phoneNumber": "+01-123-456-7890",
    "tags": [
        "example"
    ],
    "title": "Hello!"
}
</code></pre>

