Example <p>The example below shows several conversions from JSON values to other types. There are a few things to note: (1) Floating-point numbers can be converted to integers, (2) A JSON array can be converted to a standard <code>std::vector&lt;short&gt;</code>, (3) A JSON object can be converted to C++ associative containers such as <code>std::map&lt;std::string, json&gt;</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create a JSON value with different types
    json json_types =
    {
        {"boolean", true},
        {
            "number", {
                {"integer", 42},
                {"floating-point", 17.23}
            }
        },
        {"string", "Hello, world!"},
        {"array", {1, 2, 3, 4, 5}},
        {"null", nullptr}
    };

    // use implicit conversions
    bool v1 = json_types["boolean"];
    int v2 = json_types["number"]["integer"];
    short v3 = json_types["number"]["integer"];
    float v4 = json_types["number"]["floating-point"];
    int v5 = json_types["number"]["floating-point"];
    std::string v6 = json_types["string"];
    std::vector&lt;short&gt; v7 = json_types["array"];
    std::map&lt;std::string, json&gt; v8 = json_types;

    // print the conversion results
    std::cout &lt;&lt; v1 &lt;&lt; '\n';
    std::cout &lt;&lt; v2 &lt;&lt; ' ' &lt;&lt; v3 &lt;&lt; '\n';
    std::cout &lt;&lt; v4 &lt;&lt; ' ' &lt;&lt; v5 &lt;&lt; '\n';
    std::cout &lt;&lt; v6 &lt;&lt; '\n';

    for (auto i : v7)
    {
        std::cout &lt;&lt; i &lt;&lt; ' ';
    }
    std::cout &lt;&lt; "\n\n";

    for (const auto&amp; i : v8)
    {
        std::cout &lt;&lt; i.first &lt;&lt; ": " &lt;&lt; i.second &lt;&lt; '\n';
    }

    // example for an exception
    try
    {
        bool v1 = json_types["string"];
    }
    catch (const json::type_error&amp; e)
    {
        std::cout &lt;&lt; e.what() &lt;&lt; '\n';
    }
}
</code></pre> <p>Output:</p> <pre><code>1
42 42
17.23 17
Hello, world!
1 2 3 4 5 

array: [1,2,3,4,5]
boolean: true
null: null
number: {"floating-point":17.23,"integer":42}
string: "Hello, world!"
[json.exception.type_error.302] type must be boolean, but is string
</code></pre>

