    // parse and serialize JSON
    json j_complete = json::parse(text);
    std::cout &lt;&lt; std::setw(4) &lt;&lt; j_complete &lt;&lt; "\n\n";

    // define parser callback
    json::parser_callback_t cb = [](int depth, json::parse_event_t event, json &amp; parsed)
