Example: skip an object key while parsing <p>The example below demonstrates the <code>parse()</code> function with and without callback function.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // a JSON text
    const auto* text = R"(
    {
        "Image": {
            "Width":  800,
            "Height": 600,
            "Title":  "View from 15th Floor",
            "Thumbnail": {
                "Url":    "http://www.example.com/image/481989943",
                "Height": 125,
                "Width":  100
            },
            "Animated" : false,
            "IDs": [116, 943, 234, 38793]
        }
    }
    )";

    // parse and serialize JSON
    json j_complete = json::parse(text);
    std::cout &lt;&lt; std::setw(4) &lt;&lt; j_complete &lt;&lt; "\n\n";

    // define parser callback
    json::parser_callback_t cb = [](int depth, json::parse_event_t event, json &amp; parsed)
    {
        // skip object elements with key "Thumbnail"
        if (event == json::parse_event_t::key and parsed == json("Thumbnail"))
        {
            return false;
        }
        else
        {
            return true;
        }
    };

    // parse (with callback) and serialize JSON
    json j_filtered = json::parse(text, cb);
    std::cout &lt;&lt; std::setw(4) &lt;&lt; j_filtered &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
    "Image": {
        "Animated": false,
        "Height": 600,
        "IDs": [
            116,
            943,
            234,
            38793
        ],
        "Thumbnail": {
            "Height": 125,
            "Url": "http://www.example.com/image/481989943",
            "Width": 100
        },
        "Title": "View from 15th Floor",
        "Width": 800
    }
}

{
    "Image": {
        "Animated": false,
        "Height": 600,
        "IDs": [
            116,
            943,
            234,
            38793
        ],
        "Title": "View from 15th Floor",
        "Width": 800
    }
}
</code></pre> Example: how discarded values are removed <p>The example below shows where discarded values are removed. The array and the number are discarded in different ways, but in each case the parse result contains neither the value nor its key.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // a JSON text with an array and a number inside an object
    const auto* text = R"({"IDs": [116, 943], "Width": 800})";

    // discard the array when the parser reads its opening bracket
    json j_array_start = json::parse(text, [](int /*depth*/, json::parse_event_t event, json&amp; /*parsed*/)
    {
        return event != json::parse_event_t::array_start;
    });

    // discard the same array when the parser reads its closing bracket
    json j_array_end = json::parse(text, [](int /*depth*/, json::parse_event_t event, json&amp; /*parsed*/)
    {
        return event != json::parse_event_t::array_end;
    });

    // discard the number, but keep its key
    json j_value = json::parse(text, [](int /*depth*/, json::parse_event_t event, json &amp; parsed)
    {
        return !(event == json::parse_event_t::value &amp;&amp; parsed == json(800));
    });

    // discard the key of the number
    json j_key = json::parse(text, [](int /*depth*/, json::parse_event_t event, json &amp; parsed)
    {
        return !(event == json::parse_event_t::key &amp;&amp; parsed == json("Width"));
    });

    // discard the top-level object
    json j_root = json::parse(text, [](int /*depth*/, json::parse_event_t event, json&amp; /*parsed*/)
    {
        return event != json::parse_event_t::object_end;
    });

    // in every case, the discarded value is removed together with its key
    std::cout &lt;&lt; j_array_start &lt;&lt; '\n'
              &lt;&lt; j_array_end &lt;&lt; '\n'
              &lt;&lt; j_value &lt;&lt; '\n'
              &lt;&lt; j_key &lt;&lt; '\n'
              &lt;&lt; j_root &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{"Width":800}
{"Width":800}
{"IDs":[116,943]}
{"IDs":[116,943]}
null
</code></pre>

Example: apply a JSON patch <p>The following code shows how a JSON patch is applied to a value.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    // the original document
    json doc = R"(
        {
          "baz": "qux",
          "foo": "bar"
        }
    )"_json;

    // the patch
    json patch = R"(
        [
          { "op": "replace", "path": "/baz", "value": "boo" },
          { "op": "add", "path": "/hello", "value": ["world"] },
          { "op": "remove", "path": "/foo"}
        ]
    )"_json;

    // apply the patch
    json patched_doc = doc.patch(patch);

    // output original and patched document
    std::cout &lt;&lt; std::setw(4) &lt;&lt; doc &lt;&lt; "\n\n"
              &lt;&lt; std::setw(4) &lt;&lt; patched_doc &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{
    "baz": "qux",
    "foo": "bar"
}

{
    "baz": "boo",
    "hello": [
        "world"
    ]
}
</code></pre> Example: out_of_range.414 exception <p>The following code shows how a "move" operation whose "from" location is a proper prefix of its "path" location is rejected, and how the original document is left unchanged because the patch is applied to a copy.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    // the original document
    json doc = R"(
        {
          "a": { "b": 1 }
        }
    )"_json;

    // a patch that tries to move "/a" into one of its own children
    json patch = R"(
        [
          { "op": "move", "from": "/a", "path": "/a/b" }
        ]
    )"_json;

    // exception out_of_range.414
    try
    {
        json patched_doc = doc.patch(patch);
    }
    catch (const json::out_of_range&amp; e)
    {
        std::cout &lt;&lt; e.what() &lt;&lt; '\n';
    }

    // the original document is unchanged
    std::cout &lt;&lt; std::setw(4) &lt;&lt; doc &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>[json.exception.out_of_range.414] cannot move value: 'from' path '/a' is a proper prefix of 'path' '/a/b'
{
    "a": {
        "b": 1
    }
}
</code></pre>

Example: apply a JSON patch in place <p>The following code shows how a JSON patch is applied to a value.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

