Example: serialize a JSON value to UBJSON <p>The example shows the serialization of a JSON value to a byte vector in UBJSON format.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

// function to print UBJSON's diagnostic format
void print_byte(uint8_t byte)
{
    if (32 &lt; byte and byte &lt; 128)
    {
        std::cout &lt;&lt; static_cast&lt;char&gt;(byte);
    }
    else
    {
        std::cout &lt;&lt; static_cast&lt;int&gt;(byte);
    }
}

int main()
{
    // create a JSON value
    json j = R"({"compact": true, "schema": false})"_json;

    // serialize it to UBJSON
    std::vector&lt;std::uint8_t&gt; v = json::to_ubjson(j);

    // print the vector content
    for (auto&amp; byte : v)
    {
        print_byte(byte);
    }
    std::cout &lt;&lt; '\n';

    // create an array of numbers
    json array = {1, 2, 3, 4, 5, 6, 7, 8};

    // serialize it to UBJSON using default representation
    std::vector&lt;std::uint8_t&gt; v_array = json::to_ubjson(array);
    // serialize it to UBJSON using size optimization
    std::vector&lt;std::uint8_t&gt; v_array_size = json::to_ubjson(array, true);
    // serialize it to UBJSON using type optimization
    std::vector&lt;std::uint8_t&gt; v_array_size_and_type = json::to_ubjson(array, true, true);

    // print the vector contents
    for (auto&amp; byte : v_array)
    {
        print_byte(byte);
    }
    std::cout &lt;&lt; '\n';

    for (auto&amp; byte : v_array_size)
    {
        print_byte(byte);
    }
    std::cout &lt;&lt; '\n';

    for (auto&amp; byte : v_array_size_and_type)
    {
        print_byte(byte);
    }
    std::cout &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>{i7compactTi6schemaF}
[i1i2i3i4i5i6i7i8]
[#i8i1i2i3i4i5i6i7i8
[$i#i812345678
</code></pre> Example: other_error.502 exception <p>The example shows how requesting type annotations (<code>use_type</code>) without size annotations (<code>use_size</code>) throws an exception, because type-optimized containers can only be read back with a preceding size.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

int main()
{
    // create a non-empty JSON array
    json j = {1, 2, 3};

    // exception other_error.502
    try
    {
        json::to_ubjson(j, false, true);
    }
    catch (const json::other_error&amp; e)
    {
        std::cout &lt;&lt; e.what() &lt;&lt; '\n';
    }
}
</code></pre> <p>Output:</p> <pre><code>[json.exception.other_error.502] use_type requires use_size = true
</code></pre>

