Example <p>The example below parses a sequence of messages into the same document, reusing its memory instead of allocating a new document for each one.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;vector&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json_document;

int main()
{
    std::cout &lt;&lt; std::boolalpha;

    std::vector&lt;std::string&gt; messages =
    {
        R"({"id": 1})", R"({"id": 2, "tag": "x"})", R"({"id": 3})"
    };

    // parse into the same document over and over: its node index and decode
    // buffer are reused instead of being freed and reallocated for each message
    json_document doc;
    std::size_t total = 0;
    for (const auto&amp; msg : messages)
    {
        doc.read(msg);
        total += doc.root().size();
    }
    std::cout &lt;&lt; total &lt;&lt; '\n';

    // read() can also change what kind of input is owned/borrowed between calls
    doc.read(std::string(R"({"owned": true})"));
    std::cout &lt;&lt; doc.owns_source() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>4
