Example <p>The example below reads typed fields straight into C++ variables, collects a view of every array element with <code>get&lt;std::vector&lt;basic_json_view&gt;&gt;()</code> instead of a value, and converts a nested object into a user type through its <code>from_json()</code> — which runs on a <code>BasicJsonType</code> value <code>materialize()</code> builds for just that one member.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;
#include &lt;string&gt;
#include &lt;vector&gt;

using nlohmann::json_document;
using nlohmann::json_view;

// address has no direct conversion in get&lt;T&gt;(), so get&lt;address&gt;() falls back
// to materialize().get&lt;address&gt;() -- a real nlohmann::json value is built
// for just this one member, and its own from_json() runs on that
struct address
{
    std::string city;
    int zip = 0;
};

void from_json(const nlohmann::json&amp; j, address&amp; a)
{
    j.at("city").get_to(a.city);
    j.at("zip").get_to(a.zip);
}

int main()
{
    json_document doc = json_document::parse(R"(
      {
        "name": "Alice",
        "active": true,
        "orders": [1, 2, 3],
        "address": {"city": "Berlin", "zip": 10115}
      }
    )");
    const json_view customer = doc.root();

    // read typed fields straight into C++ variables -- none of these build
    // a nlohmann::json value
    const std::string name = customer["name"].get&lt;std::string&gt;();
    const bool active = customer["active"].get&lt;bool&gt;();
    std::cout &lt;&lt; name &lt;&lt; (active ? " (active)" : " (inactive)") &lt;&lt; '\n';

    // std::vector&lt;json_view&gt; keeps views of the array elements instead of
    // copies of their values
    bool first = true;
    for (const json_view order : customer["orders"].get&lt;std::vector&lt;json_view&gt;&gt;())
    {
        std::cout &lt;&lt; (first ? "" : " ") &lt;&lt; order.get&lt;int&gt;();
        first = false;
    }
    std::cout &lt;&lt; '\n';

    // everything else goes through materialize()
    const address a = customer["address"].get&lt;address&gt;();
    std::cout &lt;&lt; a.city &lt;&lt; ' ' &lt;&lt; a.zip &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>Alice (active)
1 2 3
Berlin 10115
</code></pre>

Example <p>The example below pulls one field out of a JSON text that stands in for a large API response, and shows that no <code>std::string</code> was allocated for it: the returned view still points inside the original buffer. A field that contains an escape sequence cannot point into the original text — it was decoded once into the document's own buffer instead — but still avoids a per-field allocation.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;
#include &lt;string&gt;

using nlohmann::json_document;
using nlohmann::json_view;

int main()
{
    // a "large response" stand-in: only the "id" field is ever read out of it
    const std::string text =
        R"({"id": "8f14e45f-ceea-467e-bb92-963f5e3c7a08", "note": "created via API\n", "payload": "..."})";
    const json_document doc = json_document::parse(text);
    const json_view response = doc.root();

    const json_view::string_view_t id = response["id"].get_string();
    std::cout &lt;&lt; id &lt;&lt; '\n';

    // no std::string was allocated for "id": its bytes still live inside
    // the original buffer, so id's data lies inside [text.data(),
    // text.data() + text.size())
    const bool id_in_source = id.data() &gt;= text.data() &amp;&amp; id.data() + id.size() &lt;= text.data() + text.size();
    std::cout &lt;&lt; std::boolalpha &lt;&lt; id_in_source &lt;&lt; '\n';

    // "note" contains an escape sequence ('\n'), so it was decoded once
    // into the document's own buffer -- get_string() still avoids a copy
    // into a new std::string, but the bytes no longer live inside "text"
    const json_view::string_view_t note = response["note"].get_string();
    const bool note_in_source = note.data() &gt;= text.data() &amp;&amp; note.data() + note.size() &lt;= text.data() + text.size();
    std::cout &lt;&lt; std::boolalpha &lt;&lt; note_in_source &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>8f14e45f-ceea-467e-bb92-963f5e3c7a08
true
false
</code></pre>

Example <p>The example below reads several fields of a service configuration directly into existing variables, then uses the returned reference to fold the <code>host</code>/<code>port</code> pair into a single string in the same expression.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;
#include &lt;string&gt;

using nlohmann::json_document;
using nlohmann::json_view;

int main()
{
    json_document doc = json_document::parse(R"({"host": "db.example.com", "port": 5432, "ssl": true})");
    const json_view config = doc.root();

    // get_to() writes directly into existing variables -- handy for filling
    // in the members of a struct one field at a time, without an
    // intermediate value from get&lt;T&gt;() for each one
    std::string host;
    int port = 0;
    bool ssl = false;
    config["host"].get_to(host);
    config["port"].get_to(port);
    config["ssl"].get_to(ssl);
    std::cout &lt;&lt; host &lt;&lt; ':' &lt;&lt; port &lt;&lt; (ssl ? " (tls)" : "") &lt;&lt; '\n';

    // the return value is a reference to the argument, so a call can be
    // used directly in a larger expression
    std::string other_host;
    std::cout &lt;&lt; config["host"].get_to(other_host).size() &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>db.example.com:5432 (tls)
14
</code></pre>

Example <p>The example below classifies several parsed documents by the type of their root value, without materializing any of them into a <code>BasicJsonType</code> value.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json_view.hpp&gt;

using nlohmann::json_document;

int main()
{
    std::cout &lt;&lt; std::boolalpha;

    // several incoming messages, one json_document per message. type() and
    // is_*() only look at the flat index built by parse(); no nlohmann::json
    // tree exists yet, and none is built unless materialize() is called
    json_document d_null = json_document::parse("null");
    json_document d_bool = json_document::parse("true");
    json_document d_int = json_document::parse("-42");
    json_document d_unsigned = json_document::parse("42");
    json_document d_float = json_document::parse("4.2");
    json_document d_string = json_document::parse(R"("hi")");
    json_document d_array = json_document::parse("[1, 2, 3]");
    json_document d_object = json_document::parse(R"({"a": 1})");

    std::cout &lt;&lt; d_null.root().is_null() &lt;&lt; '\n';
    std::cout &lt;&lt; d_bool.root().is_boolean() &lt;&lt; '\n';
    std::cout &lt;&lt; d_int.root().is_number() &lt;&lt; ' ' &lt;&lt; d_int.root().is_number_integer() &lt;&lt; '\n';
    std::cout &lt;&lt; d_unsigned.root().is_number_unsigned() &lt;&lt; '\n';
    std::cout &lt;&lt; d_float.root().is_number_float() &lt;&lt; '\n';
    std::cout &lt;&lt; d_string.root().is_string() &lt;&lt; '\n';
    std::cout &lt;&lt; d_array.root().is_array() &lt;&lt; ' ' &lt;&lt; d_array.root().is_structured() &lt;&lt; '\n';
    std::cout &lt;&lt; d_object.root().is_object() &lt;&lt; ' ' &lt;&lt; d_object.root().is_primitive() &lt;&lt; '\n';

    // JSON text can never produce a binary value: is_binary() is always false
    std::cout &lt;&lt; d_array.root().is_binary() &lt;&lt; '\n';

    // a default-constructed view, and the root of a document that failed to
    // parse without exceptions, are both discarded
    nlohmann::json_view invalid;
    json_document failed = json_document::parse("not json", /* allow_exceptions */ false);
    std::cout &lt;&lt; invalid.is_discarded() &lt;&lt; '\n';
    std::cout &lt;&lt; failed.root().is_discarded() &lt;&lt; '\n';

    // type() returns the same value_t enumeration as basic_json::type()
    std::cout &lt;&lt; (d_object.root().type() == nlohmann::json::value_t::object) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>true
true
true true
true
true
true
true true
true false
false
true
true
true
</code></pre>

