              &lt;&lt; "\"" &lt;&lt; ptr1 &lt;&lt; "\" &lt;=&gt; \"" &lt;&lt; ptr3 &lt;&lt; "\": " &lt;&lt; to_string(ptr1 &lt;=&gt; ptr3) &lt;&lt; '\n' // *NOPAD*
              &lt;&lt; "\"" &lt;&lt; ptr1 &lt;&lt; "\" &lt;=&gt; \"" &lt;&lt; ptr4 &lt;&lt; "\": " &lt;&lt; to_string(ptr1 &lt;=&gt; ptr4) &lt;&lt; std::endl; // *NOPAD*
}
