enum class Choice
{
    first,
    second,
};

int main()
{
    // normally invokes to_json serialization function but with JSON_DISABLE_ENUM_SERIALIZATION defined, it does not
    const json j = Choice::first; 

    // normally invokes from_json parse function but with JSON_DISABLE_ENUM_SERIALIZATION defined, it does not
    Choice ch = j.get&lt;Choice&gt;();
}
</code></pre> Example: Serialize enum macro <p>The code below forces the library not to create default serialization/deserialization functions <code>from_json</code> and <code>to_json</code>, but uses <code>NLOHMANN_JSON_SERIALIZE_ENUM</code> to parse and serialize the enum.</p> <pre><code>#define JSON_DISABLE_ENUM_SERIALIZATION 1
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

enum class Choice
{
    first,
    second,
};

NLOHMANN_JSON_SERIALIZE_ENUM(Choice,
{
    { Choice::first, "first" },
    { Choice::second, "second" },
})

int main()
{
    // uses user-defined to_json function defined by macro
    const json j = Choice::first; 

    // uses user-defined from_json function defined by macro
    Choice ch = j.get&lt;Choice&gt;();
}
</code></pre> Example: User-defined serialization/deserialization functions <p>The code below forces the library not to create default serialization/deserialization functions <code>from_json</code> and <code>to_json</code>, but uses user-defined functions to parse and serialize the enum.</p> <pre><code>#define JSON_DISABLE_ENUM_SERIALIZATION 1
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

enum class Choice
{
    first,
    second,
};

void from_json(const json&amp; j, Choice&amp; ch)
{
    auto value = j.get&lt;std::string&gt;();
    if (value == "first")
    {
        ch = Choice::first;
    }
    else if (value == "second")
    {
        ch = Choice::second;
    }
}

void to_json(json&amp; j, const Choice&amp; ch)
{
    if (ch == Choice::first)
    {
        j = "first";
    }
    else if (ch == Choice::second)
    {
        j = "second";
    }
}

int main()
{
    // uses user-defined to_json function
    const json j = Choice::first; 

    // uses user-defined from_json function
    Choice ch = j.get&lt;Choice&gt;();
}
</code></pre>

