    std::cout &lt;&lt; "serialization: " &lt;&lt; j &lt;&lt; '\n';
}
</code></pre>

Example: NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE_WITH_NAMES <p>Consider the following complete example:</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

namespace ns
{
struct person
{
    std::string name;
    std::string address;
    int age;
};

NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE_WITH_NAMES(person, "json_name", name, "json_address", address, "json_age", age)
} // namespace ns

int main()
{
    ns::person p = {"Ned Flanders", "744 Evergreen Terrace", 60};

    // serialization: person -&gt; json
    json j = p;
    std::cout &lt;&lt; "serialization: " &lt;&lt; j &lt;&lt; '\n';

    // deserialization: json -&gt; person
    json j2 = R"({"json_address": "742 Evergreen Terrace", "json_age": 40, "json_name": "Homer Simpson"})"_json;
    auto p2 = j2.template get&lt;ns::person&gt;();

    // incomplete deserialization:
    json j3 = R"({"json_address": "742 Evergreen Terrace", "json_name": "Maggie Simpson"})"_json;
    try
    {
        auto p3 = j3.template get&lt;ns::person&gt;();
    }
    catch (const json::exception&amp; e)
    {
        std::cout &lt;&lt; "deserialization failed: " &lt;&lt; e.what() &lt;&lt; '\n';
    }
}
</code></pre> <p>Output:</p> <pre><code>serialization: {"json_address":"744 Evergreen Terrace","json_age":60,"json_name":"Ned Flanders"}
deserialization failed: [json.exception.out_of_range.403] key 'json_age' not found
</code></pre> <p>Notes:</p> <ul> <li><code>ns::person</code> is default-constructible. This is a requirement for using the macro.</li> <li><code>ns::person</code> has only public member variables. This makes <code>NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE_WITH_NAMES</code> applicable.</li> <li>The macro <code>NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE_WITH_NAMES</code> is used outside the class, but inside its namespace <code>ns</code>.</li> <li>A missing key "age" in the deserialization yields an exception. To fall back to the default value,   <code>NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE_WITH_DEFAULT_WITH_NAMES</code> can be used.</li> </ul> <p>The macro is equivalent to:</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;
using namespace nlohmann::literals;

namespace ns
{
struct person
{
    std::string name;
    std::string address;
    int age;
};

template &lt;typename BasicJsonType, nlohmann::detail::enable_if_t&lt;nlohmann::detail::is_basic_json&lt;BasicJsonType&gt;::value, int&gt; = 0&gt;
void to_json(BasicJsonType&amp; nlohmann_json_j, const person&amp; nlohmann_json_t)
{
    nlohmann_json_j["json_name"] = nlohmann_json_t.name;
    nlohmann_json_j["json_address"] = nlohmann_json_t.address;
    nlohmann_json_j["json_age"] = nlohmann_json_t.age;
}

template &lt;typename BasicJsonType, nlohmann::detail::enable_if_t&lt;nlohmann::detail::is_basic_json&lt;BasicJsonType&gt;::value, int&gt; = 0&gt;
void from_json(const BasicJsonType&amp; nlohmann_json_j, person&amp; nlohmann_json_t)
{
    nlohmann_json_j.at("json_name").get_to(nlohmann_json_t.name);
    nlohmann_json_j.at("json_address").get_to(nlohmann_json_t.address);
    nlohmann_json_j.at("json_age").get_to(nlohmann_json_t.age);
}
} // namespace ns

int main()
{
    ns::person p = {"Ned Flanders", "744 Evergreen Terrace", 60};

    // serialization: person -&gt; json
    json j = p;
    std::cout &lt;&lt; "serialization: " &lt;&lt; j &lt;&lt; '\n';

    // deserialization: json -&gt; person
    json j2 = R"({"json_address": "742 Evergreen Terrace", "json_age": 40, "json_name": "Homer Simpson"})"_json;
    auto p2 = j2.template get&lt;ns::person&gt;();

    // incomplete deserialization:
    json j3 = R"({"json_address": "742 Evergreen Terrace", "json_name": "Maggie Simpson"})"_json;
    try
    {
        auto p3 = j3.template get&lt;ns::person&gt;();
    }
    catch (const json::exception&amp; e)
    {
        std::cout &lt;&lt; "deserialization failed: " &lt;&lt; e.what() &lt;&lt; '\n';
    }
}
</code></pre>

Example <p>The example shows how to use <code>NLOHMANN_JSON_NAMESPACE</code> instead of just <code>nlohmann</code>, as well as how to output the value of <code>NLOHMANN_JSON_NAMESPACE</code>.</p> <pre><code>#include &lt;iostream&gt;
