Example <p>The example shows how to use <code>NLOHMANN_JSON_NAMESPACE_BEGIN</code>/<code>NLOHMANN_JSON_NAMESPACE_END</code> from the How do I convert third-party types? page.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;optional&gt;
#include &lt;nlohmann/json.hpp&gt;

// partial specialization (see https://json.nlohmann.me/features/arbitrary_types/)
NLOHMANN_JSON_NAMESPACE_BEGIN
template &lt;typename T&gt;
struct adl_serializer&lt;std::optional&lt;T&gt;&gt;
{
    static void to_json(json&amp; j, const std::optional&lt;T&gt;&amp; opt)
    {
        if (opt == std::nullopt)
        {
            j = nullptr;
        }
        else
        {
            j = *opt;
        }
    }
};
