Example: Basic usage <p>The example shows how <code>NLOHMANN_JSON_SERIALIZE_ENUM</code> can be used to serialize/deserialize both classical enums and C++11 enum classes:</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
enum TaskState
{
    TS_STOPPED,
    TS_RUNNING,
    TS_COMPLETED,
    TS_INVALID = -1
};

NLOHMANN_JSON_SERIALIZE_ENUM(TaskState,
{
    { TS_INVALID, nullptr },
    { TS_STOPPED, "stopped" },
    { TS_RUNNING, "running" },
    { TS_COMPLETED, "completed" }
})

enum class Color
{
    red, green, blue, unknown
};

NLOHMANN_JSON_SERIALIZE_ENUM(Color,
{
    { Color::unknown, "unknown" }, { Color::red, "red" },
    { Color::green, "green" }, { Color::blue, "blue" }
})
} // namespace ns

int main()
{
    // serialization
    json j_stopped = ns::TS_STOPPED;
    json j_red = ns::Color::red;
    std::cout &lt;&lt; "ns::TS_STOPPED -&gt; " &lt;&lt; j_stopped
              &lt;&lt; ", ns::Color::red -&gt; " &lt;&lt; j_red &lt;&lt; '\n';

    // deserialization
    json j_running = "running";
    json j_blue = "blue";
    auto running = j_running.get&lt;ns::TaskState&gt;();
    auto blue = j_blue.get&lt;ns::Color&gt;();
    std::cout &lt;&lt; j_running &lt;&lt; " -&gt; " &lt;&lt; running
              &lt;&lt; ", " &lt;&lt; j_blue &lt;&lt; " -&gt; " &lt;&lt; static_cast&lt;int&gt;(blue) &lt;&lt; '\n';

    // deserializing undefined JSON value to enum
    // (where the first map entry above is the default)
    json j_pi = 3.14;
    auto invalid = j_pi.get&lt;ns::TaskState&gt;();
    auto unknown = j_pi.get&lt;ns::Color&gt;();
    std::cout &lt;&lt; j_pi &lt;&lt; " -&gt; " &lt;&lt; invalid &lt;&lt; ", "
              &lt;&lt; j_pi &lt;&lt; " -&gt; " &lt;&lt; static_cast&lt;int&gt;(unknown) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>ns::TS_STOPPED -&gt; "stopped", ns::Color::red -&gt; "red"
"running" -&gt; 1, "blue" -&gt; 2
3.14 -&gt; -1, 3.14 -&gt; 3
</code></pre> Example: Multiple conversions for one enumerator <p>The example shows how to use multiple conversions for a single enumerator. In the example, <code>Color::red</code> will always be serialized to <code>"red"</code>, because the first occurring conversion. The second conversion, however, offers an alternative deserialization from <code>"rot"</code> to <code>Color::red</code>.</p> <pre><code>#include &lt;iostream&gt;
#include &lt;nlohmann/json.hpp&gt;

using nlohmann::json;

namespace ns
{
enum class Color
{
    red, green, blue, unknown
};

NLOHMANN_JSON_SERIALIZE_ENUM(Color,
{
    { Color::unknown, "unknown" }, { Color::red, "red" },
    { Color::green, "green" }, { Color::blue, "blue" },
    { Color::red, "rot" } // a second conversion for Color::red
})
}

int main()
{
    // serialization
    json j_red = ns::Color::red;
    std::cout &lt;&lt; static_cast&lt;int&gt;(ns::Color::red) &lt;&lt; " -&gt; " &lt;&lt; j_red &lt;&lt; '\n';

    // deserialization
    json j_rot = "rot";
    auto rot = j_rot.get&lt;ns::Color&gt;();
    auto red = j_red.get&lt;ns::Color&gt;();
    std::cout &lt;&lt; j_rot &lt;&lt; " -&gt; " &lt;&lt; static_cast&lt;int&gt;(rot) &lt;&lt; '\n';
    std::cout &lt;&lt; j_red &lt;&lt; " -&gt; " &lt;&lt; static_cast&lt;int&gt;(red) &lt;&lt; '\n';
}
</code></pre> <p>Output:</p> <pre><code>0 -&gt; "red"
"rot" -&gt; 0
"red" -&gt; 0
</code></pre>

